    if (step?.executeAttempted) return this.refreshPending(step);
    if (step?.status === "FAILED") throw fail2("PREVIOUS_STEP_FAILED", "\u539F\u4EA4\u6613\u6B65\u9AA4\u5931\u8D25\uFF0C\u4E0D\u81EA\u52A8\u91CD\u53D1");
    developerMode(this.settings);
    const wire = wireTx(request);
