    if (preview.expiresAt && Number(preview.expiresAt) <= Date.now()) throw fail2("PREVIEW_EXPIRED", "BAW preview \u5DF2\u8FC7\u671F\uFF0C\u672A\u6267\u884C");
    step = {
      kind: "contract",
      name,
      status: "PREVIEWED",
      request: wire,
      requestId: preview.requestId,
      requireConfirmation: preview.requireConfirmation,
      risks: preview.risks,
      executeAttempted: false
    };
